import{_ as l,a0 as u,w as a,s as p,ao as r,I as s,x as n,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"試試只用U盤加載Linux系統 | LCTT x X-CMD","titleTemplate":false,"description":"試試只用U盤加載Linux系統 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"試試只用U盤加載Linux系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"試試只用U盤加載Linux系統 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141030 Test drive Linux with nothing but a flash drive","title":"試試只用U盤加載Linux系統","tag":"201502","desc":""},"relativePath":"201502/20141030 Test drive Linux with nothing but a flash drive.md","filePath":"[post].md"}'),d={name:"201502/20141030 Test drive Linux with nothing but a flash drive.md"};function g(f,t,m,x,T,b){const i=u("Link");return a(),p("div",null,[t[23]||(t[23]=r('<h1 id="試試只用u盤加載linux系統" tabindex="-1">試試只用U盤加載Linux系統 <a class="header-anchor" href="#試試只用u盤加載linux系統" aria-label="Permalink to “試試只用U盤加載Linux系統”">​</a></h1><p>也許你聽過Linux並對它有點好奇，終於想要實際體驗一下，但可能不知道從哪兒開始。</p><p>很可能你已經在網上搜索過一些信息，然後遇到一些像雙系統和虛擬機這樣的詞彙。它們對你來説也許太專業了，所以你肯定不會僅僅為了嘗試一下Linux而犧牲正在使用的操作系統。那我們該怎麼辦？</p><p>如果你手上正好有個U盤的話，那就可以試試做一個USB Linux啓動盤。它是一個包含了整個操作系統並可以直接引導開機的U盤。創建它並不需要什麼專業技術能力，讓我們來看看怎麼做，以及如何從USB引導進入Linux系統。</p><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/OSDC_Penguin_Image_520x292_12324207_0714_mm_v1a.png" alt="Penguins gathered together: Linux for the win"></p><h3 id="你需要準備的" tabindex="-1">你需要準備的 <a class="header-anchor" href="#你需要準備的" aria-label="Permalink to “你需要準備的”">​</a></h3><p>除了一台台式機或筆記本電腦外，你還需要：</p>',7)),s("ul",null,[t[6]||(t[6]=s("li",null,"一個空白的U盤-最好容量能有4GB或更多。",-1)),s("li",null,[t[1]||(t[1]=n("一個你想嘗試的Linux發行版",-1)),e(i,{href:"http://en.wikipedia.org/wiki/ISO_image"},{default:o(()=>[...t[0]||(t[0]=[n("ISO鏡像",-1)])]),_:1}),t[2]||(t[2]=n("（一種把所有磁盤內容打包起來的檔案文件）。待會再詳細介紹。",-1))]),s("li",null,[t[4]||(t[4]=n("一個叫",-1)),e(i,{href:"http://unetbootin.sourceforge.net/"},{default:o(()=>[...t[3]||(t[3]=[n("Unetbootin",-1)])]),_:1}),t[5]||(t[5]=n("的應用程序，它是一個開源的，跨平台的工具，用來創建USB啓動盤。運行它並不需要啓動Linux。在下面的教程中，我是在MacBook上運行的Unetbootiin（LCTT 譯註：它還有 Windows 和 Linux 版本）。",-1))])]),t[24]||(t[24]=r('<h3 id="開始幹活" tabindex="-1">開始幹活 <a class="header-anchor" href="#開始幹活" aria-label="Permalink to “開始幹活”">​</a></h3><p>把U盤插到你電腦的USB端口上，然後啓動Unetbootin。然後會要求你輸入當前電腦的登錄密碼。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-main.png" alt="Unetbootin main window"></p><p>還記得之前提到的ISO鏡像文件嗎？有兩種方式可以獲得：要麼自己從你想嘗試的Linux發行版網站上下載，或者讓Unetbootin幫你下載。如果選後者，在窗口頂部點擊<strong>選擇發行版</strong>，選擇你想下載的發行版，然後點擊<strong>選擇版本</strong>來選擇你希望嘗試的發行版版本。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-download-distro.png" alt="Downloading a Linux distribution"></p><p>或者，你也可以自己下載發行版。通常，我想嘗試的Linux發行版都沒有在列表中。如果選擇自己下載，那麼點擊<strong>磁盤鏡像</strong>，然後點擊按鈕來選擇你下載好的.iso文件。</p><p>注意到下面的選項<strong>預留每次重新啓動後保存文件的空間（僅Ubuntu有效）</strong>嗎？如果你嘗試的是Ubuntu或它的任一個衍生版（比如Lubuntu或Xubuntu），你可以在U盤上留出幾M空間用來保存文件，比如網頁書籤或你自己創建的文檔。當用這個U盤下次啓動Ubuntu的時候，你可以繼續使用這些文件。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-ready-to-go.png" alt="Ready to create a live USB"></p><p>在加載好ISO鏡像後，點擊<strong>確定</strong>。Unetbootin大概需要不到10分鐘來創建USB啓動盤。</p><p><img src="http://opensource.com/sites/default/files/images/life-uploads/unetbootin-creating-disk.png" alt="Creating the live USB"></p><h3 id="檢驗usb啓動盤" tabindex="-1">檢驗USB啓動盤 <a class="header-anchor" href="#檢驗usb啓動盤" aria-label="Permalink to “檢驗USB啓動盤”">​</a></h3>',11)),s("p",null,[t[8]||(t[8]=n("這個時候，你需要擁抱一下自己內在的極客精神。這不會太難，不過你將需要進入",-1)),e(i,{href:"http://en.wikipedia.org/wiki/BIOS"},{default:o(()=>[...t[7]||(t[7]=[n("BIOS",-1)])]),_:1}),t[9]||(t[9]=n("去偷看一下你的電腦內部空間。你的電腦的BIOS會加載各種硬件，並控制電腦操作系統的引導或啓動。",-1))]),t[25]||(t[25]=r('<p>BIOS通常會按這個順序搜索操作系統（或者類似的順序）：硬盤，然後是CD/DVD光驅，然後是外部存儲設備。你需要調整這個順序，讓外部存儲設備（在這裏，指的是你的U盤啓動盤）成為BIOS第一個搜索的設備。</p><p>要做到這一點，請把U盤插到電腦上再重啓電腦。在看到提示信息<strong>Press F2 to enter setup</strong>之後，按它要求的做。在有的電腦上，這個鍵可能是F10。</p><p>在BIOS裏，用鍵盤上的向右方向鍵切換到<strong>Boot</strong>菜單。然後你將看到你電腦上的驅動器列表。使用鍵盤上的向下方向鍵選中名字為<strong>USB HDD</strong>的選項，然後按下<strong>F6</strong>移動這個選項到列表的頂部。</p><p>完成後，按下<strong>F10</strong>來保存改動。然後你會從BIOS裏被踢出來，然後電腦會自己啓動。等一小會，你就會看到一個你正在嘗試的Linux發行版的啓動菜單。選擇<strong>Run without installing</strong>（或者最類似的選項）。</p><p>在進入桌面後，你可以連接上無線或有線網絡，看看網頁，試一試預裝的軟件。你還可以看看，比如説，你的打印機或掃描儀是否能在你試的這個發行版下正常工作。你要是真的想不開，也可以去摸一下命令列。</p><h3 id="能幹什麼" tabindex="-1">能幹什麼 <a class="header-anchor" href="#能幹什麼" aria-label="Permalink to “能幹什麼”">​</a></h3><p>根據你嘗試的Linux發行版和你使用的U盤的速度，操作系統可能會需要較長的時間來加載，而且很可能比直接裝到硬盤上會慢一點。</p><p>還有，你也只能運行Linux發行版裏預裝好的基本軟件。通常會有網頁瀏覽器，一個文字處理軟件，一個文本編輯器，一個媒體播放器，一個相片瀏覽器，以及一套實用工具。這些應該足夠給你使用Linux的感覺了。</p><p>如果你決定使用Linux，你可以雙擊安裝器從U盤安裝到硬盤。</p><hr>',10)),s("p",null,[t[11]||(t[11]=n("via: ",-1)),e(i,{href:"https://opensource.com/life/14/10/test-drive-linux-nothing-flash-drive"},{default:o(()=>[...t[10]||(t[10]=[n("https://opensource.com/life/14/10/test-drive-linux-nothing-flash-drive",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=n("作者：",-1)),e(i,{href:"https://opensource.com/users/scottnesbitt"},{default:o(()=>[...t[12]||(t[12]=[n("Scott Nesbitt",-1)])]),_:1}),t[16]||(t[16]=n(" 譯者：",-1)),e(i,{href:"https://github.com/zpl1025"},{default:o(()=>[...t[13]||(t[13]=[n("zpl1025",-1)])]),_:1}),t[17]||(t[17]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[20]||(t[20]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[n("LCTT",-1)])]),_:1}),t[21]||(t[21]=n(" 原創翻譯，",-1)),e(i,{href:"http://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[n("Linux中國",-1)])]),_:1}),t[22]||(t[22]=n(" 榮譽推出",-1))])])}const h=l(d,[["render",g]]);export{S as __pageData,h as default};
